// Parse TradingView alert payload
const body = $input.first().json.body || $input.first().json;

// TradingView envoie des alertes texte ou JSON
// Format attendu dans l'alerte TradingView :
// {"symbol":"{{ticker}}","timeframe":"{{interval}}","close":"{{close}}","time":"{{time}}","chart_url":"https://www.tradingview.com/chart/..."}

let payload;
try {
  payload = typeof body === 'string' ? JSON.parse(body) : body;
} catch(e) {
  payload = {
    symbol: 'XAUUSD',
    timeframe: 'H1',
    close: body.toString(),
    time: new Date().toISOString(),
    chart_url: null
  };
}

return [{
  json: {
    symbol: payload.symbol || 'UNKNOWN',
    timeframe: payload.interval || payload.timeframe || 'H1',
    close: parseFloat(payload.close || 0),
    open: parseFloat(payload.open || 0),
    high: parseFloat(payload.high || 0),
    low: parseFloat(payload.low || 0),
    volume: parseFloat(payload.volume || 0),
    time: payload.time || new Date().toISOString(),
    chart_url: payload.chart_url || null,
    raw_payload: payload
  }
}];

