// Parse la réponse Claude et extrait le JSON du signal
const response = $input.first().json;
const content = response.content?.[0]?.text || '{}';

let signal;
try {
  // Claude retourne du JSON pur
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  signal = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch(e) {
  signal = {
    direction: 'NEUTRAL',
    score: 0,
    confidence: 0,
    entry_price: 0,
    stop_loss: 0,
    take_profit_1: 0,
    take_profit_2: 0,
    risk_reward: 0,
    analysis: 'Erreur de parsing: ' + content.substring(0, 200)
  };
}

const parseData = $('🔍 Parse Alert').item.json;
const snapshotData = $('💾 Save Snapshot').item.json;

return [{
  json: {
    snapshot_id: snapshotData.id,
    symbol: parseData.symbol,
    timeframe: parseData.timeframe,
    direction: signal.direction || 'NEUTRAL',
    score: parseFloat(signal.score || 0),
    confidence: parseFloat(signal.confidence || 0),
    entry_price: parseFloat(signal.entry_price || 0),
    stop_loss: parseFloat(signal.stop_loss || 0),
    take_profit_1: parseFloat(signal.take_profit_1 || 0),
    take_profit_2: parseFloat(signal.take_profit_2 || 0),
    risk_reward: parseFloat(signal.risk_reward || 0),
    ai_analysis: signal.analysis || '',
    should_trade: signal.score >= 7 && signal.direction !== 'NEUTRAL'
  }
}];
